import jetbrains.buildServer.configs.kotlin.v2019_2.*
import jetbrains.buildServer.configs.kotlin.v2019_2.buildSteps.msBuild
import jetbrains.buildServer.configs.kotlin.v2019_2.buildSteps.nuGetInstaller
import jetbrains.buildServer.configs.kotlin.v2019_2.triggers.vcs
import jetbrains.buildServer.configs.kotlin.v2019_2.vcs.GitVcsRoot

version = "2024.03"

project {
    description = "Acme WebForms Portal"

    vcsRoot(WebFormsSolutionVcs)

    buildType(Build)
    buildType(OctoPack)
}

object WebFormsSolutionVcs : GitVcsRoot({
    name = "webforms-solution"
    url = "https://bitbucket.internal.acmecorp.com/scm/acme/webforms-solution.git"
    branch = "refs/heads/main"
    branchSpec = "+:refs/heads/*"
    authMethod = password {
        userName = "tc-service-account"
        password = "credentialsJSON:a1b2c3d4-e5f6-7890-abcd-ef1234567890"
    }
    checkoutSubmodules = GitVcsRoot.CheckoutSubmodules.IGNORE
})

object Build : BuildType({
    name = "Build"
    artifactRules = "Web/bin/Release/** => WebApp.%build.number%.zip"

    vcs {
        root(WebFormsSolutionVcs)
    }

    steps {
        nuGetInstaller {
            toolPath = "%teamcity.tool.NuGet.CommandLine.6.4.0%"
            projects = "WebApp.sln"
        }
        msBuild {
            path = "WebApp.sln"
            version = MSBuildStep.MSBuildVersion.V17
            toolsVersion = MSBuildStep.MSBuildToolsVersion.V17_0
            args = "/p:Configuration=Release /p:DeployOnBuild=false"
        }
    }

    triggers {
        vcs {
            branchFilter = "+:*"
        }
    }
})

object OctoPack : BuildType({
    name = "OctoPack & Push"
    artifactRules = "*.nupkg"

    dependencies {
        snapshot(Build) {}
        artifacts(Build) {
            artifactRules = "WebApp.%build.number%.zip => ."
        }
    }

    steps {
        step {
            type = "octopus.pack"
            param("octopus_packageid", "Acme.WebApp")
            param("octopus_packageversion", "%build.number%")
        }
        step {
            type = "octopus.push"
            param("octopus_host", "%octopus.server.url%")
            param("octopus_apikey", "%octopus.api.key%")
        }
    }
})
